"""本地只读原生取证；不导航、不领取/释放资源、不修改配置。"""
import sys,subprocess,json,pathlib,os,re,time,hashlib,xml.etree.ElementTree as E
from local_transport import local_environment

def probe(c,run_command=subprocess.run,now=time.time):
 env=local_environment(c);out={};cli=c['phone_controller']
 for command,key in [('preflight','preflight'),('lock-status','local_lock')]:
  try:
   r=run_command([cli,'--profile',c['profile'],command],capture_output=True,text=True,timeout=12,env=env)
   if r.returncode==0:
    if command=='preflight':
     fields=dict(l.split('=',1) for l in r.stdout.splitlines() if '=' in l)
     m=re.search(r'([A-Za-z][A-Za-z0-9_.]+)/',fields.get('foreground',''));fields['foreground_package']=m.group(1) if m else None
    else:fields=dict(re.findall(r'(\w+)=([^\s]+)',r.stdout))
    out[key]=fields
  except Exception:pass
 try:
  hardware=run_command([sys.executable,str(pathlib.Path(c['runtime_root'])/'adb-managed-client.py'),'-s',c['adb_serial'],'shell','getprop','ro.serialno'],capture_output=True,text=True,timeout=8,env=env)
  if hardware.returncode==0 and re.fullmatch(r'[A-Za-z0-9_.:-]{1,160}',hardware.stdout.strip()) and 'preflight' in out:
   out['preflight']['hardware_serial']=hardware.stdout.strip()
 except Exception:pass
 root=pathlib.Path(c['native_root'])
 try:
  if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]{0,119}',c['run']):raise ValueError('RUN_REQUIRED')
  files=sorted(root.glob(c['run']+'*-profile.xml'),key=lambda p:p.stat().st_mtime,reverse=True)
  if files:
   p=files[0]
   if p.is_symlink() or p.resolve().parent!=root.resolve():raise ValueError('NATIVE_FILE_SCOPE')
   raw=p.read_bytes();tree=E.fromstring(raw);ids=set();own=False;foreign=False
   for node in tree.iter('node'):
    own=own or node.get('text')=='编辑主页' or node.get('content-desc','').startswith('切换账号')
    foreign=foreign or node.get('content-desc')=='私信'
    for text in [node.get('text',''),node.get('content-desc','')]:
     m=re.fullmatch(r'(?:抖音号[:：]\s*)([A-Za-z0-9_.-]+)',text.strip())
     if m:ids.add(m.group(1))
   out['account']={'account':next(iter(ids)) if len(ids)==1 and own and not foreign else None,'own_profile':own and not foreign,'age_s':now()-p.stat().st_mtime,'source':p.name,'sha256':hashlib.sha256(raw).hexdigest()}
 except Exception:pass
 try:
  live=[]
  for p in root.glob(c['run']+'*.rec.pid'):
   pid=int(p.read_text().strip())
   try:os.kill(pid,0);live.append(pid)
   except ProcessLookupError:pass
   except Exception:live.append(pid)
  ps=run_command(['/bin/ps','-axo','pid,command'],capture_output=True,text=True,timeout=5)
  if ps.returncode==0:
   count=sum(1 for line in ps.stdout.splitlines() if c['profile'] in line and 'douyin-phone-adb' in line)
   out['operations']={'live_pids':live,'native_process_count':count}
 except Exception:pass
 return out

if __name__=='__main__':print(json.dumps(probe(json.load(sys.stdin))))

