import fs from 'node:fs';
import path from 'node:path';
import {createRequire} from 'node:module';
import {readLocalLock} from './lock-readback.mjs';
import {verifyCleanup} from './cleanup-result.mjs';
import {main as readback} from './production-readback-local.mjs';
const request=JSON.parse(fs.readFileSync(0,'utf8')),c=request.context;
const identity=Object.fromEntries(['task_id','run_id','run_tag','workflow','activity','attempt'].map(k=>[k,request[k]]));
if(request.phase==='end')console.log(JSON.stringify(await (request.workflow==='104'?(await import('./outreach104/checker104.mjs')).verify104(request,path.dirname(new URL(import.meta.url).pathname)):request.activity==='cleanup'?verifyCleanup(request):readback(request))));
else{
 const checks=[];const add=(id,pass,source,observation)=>checks.push({id,status:pass===null?'unknown':pass?'passed':'failed',evidence:[{source,observation}]});
 let pool;
 try{
  const cache=fs.readFileSync(path.join(process.env.HOME,'.credentials/cecelia-internal.env'),'utf8');
  const row=cache.split('\n').find(l=>/^(BRAIN_INTERNAL_TOKEN|CECELIA_INTERNAL_TOKEN)=/.test(l));const raw=row.slice(row.indexOf('=')+1);let token;try{token=JSON.parse(raw);}catch{token=raw;}
  const get=async p=>{const r=await fetch('http://localhost:5221/api/brain/'+p,{headers:{'X-Internal-Token':token},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('BRAIN_UNAVAILABLE');return r.json()};
  const task=await get('tasks/'+request.task_id),t=task.task??task,root=await get('tasks/'+c.root_task_id),rt=root.task??root;
  add('task',t.status==='in_progress'&&t.claimed_by===c.actor&&rt.status==='in_progress'&&rt.claimed_by===c.actor,'Brain/tasks',{task_id:t.id,status:t.status,actor:t.claimed_by,root_status:rt.status});
  if(request.checks.includes('resources')){
   const locks=await get('device-locks');const cent=locks.locks.find(l=>l.device_name===c.serial);
   const local=readLocalLock(c);const fields=local.fields;
   const allowFree=['preflight','cleanup'].includes(request.activity);
   const owned=cent?.locked_by===c.central_owner&&Date.parse(cent.expires_at)>Date.now();
   const localOwned=fields.lock==='held'&&fields.owner===c.local_owner&&fields.stale==='false';
   const journals=path.join(process.cwd(),'receipts');const unknown=fs.existsSync(journals)?fs.readdirSync(journals).filter(n=>n.endsWith('.json')).filter(n=>JSON.parse(fs.readFileSync(path.join(journals,n))).state==='unknown'):[];
   add('resources',!local.valid?null:(owned||allowFree&&cent?.locked_by===null)&&(localOwned||allowFree&&fields.lock==='free')&&unknown.length===0,'Brain/device-locks + controller/lock-status + action-journal',{central:cent?{owner:cent.locked_by,lease_version:cent.lease_version}:null,local:fields,lock_probe:local.attempts,unknown_actions:unknown});
  }
  const require=createRequire(path.join(c.runtime_root,'package.json')),{Pool}=require('pg');const privateDB=JSON.parse(fs.readFileSync(path.join(process.env.HOME,'.credentials/zenithjoy-db.json')));
  pool=new Pool({connectionString:privateDB.DATABASE_URL,connectionTimeoutMillis:10000,max:1});
  const client=await pool.connect();try{
   await client.query('BEGIN READ ONLY');await client.query("SET LOCAL statement_timeout='10000ms'");
   const db=(await client.query('SELECT current_database() as name')).rows[0];
   const rows=(await client.query('SELECT company_id,tenant_id,config_version,config_status,runtime_config FROM zenithjoy.tenant_company_profiles WHERE company_id=$1',[c.company_id])).rows;
   const p=rows[0];add('policy',db.name==='zenithjoy'&&rows.length===1&&p.tenant_id===c.tenant_id&&p.config_status==='enabled'&&Number(p.config_version)===c.verification.policy_version&&p.runtime_config.policy_id===c.verification.policy_id,'PG/tenant_company_profiles',{database:db.name,company_id:p?.company_id,tenant_id:p?.tenant_id,version:p?.config_version,status:p?.config_status,policy_id:p?.runtime_config.policy_id});
   await client.query('ROLLBACK');
  }finally{client.release();}
 }catch(e){for(const id of request.checks)if(!checks.some(x=>x.id===id))add(id,null,'start-checker',{error:/^[A-Z_]+$/.test(e.message)?e.message:'READBACK_UNAVAILABLE'});}
 finally{if(pool)await pool.end();}
 console.log(JSON.stringify({identity,nonce:request.nonce,outcome:checks.every(x=>x.status==='passed')?'passed':'blocked',checks,output:{start_verified:checks.every(x=>x.status==='passed')}}));
}

